        write_fail_10 = _RANDOM[6'h29][18];
        write_fail_11 = _RANDOM[6'h29][19];
        write_fail_12 = _RANDOM[6'h29][20];
        write_fail_13 = _RANDOM[6'h29][21];
        write_fail_14 = _RANDOM[6'h29][22];
        scoreboard_error = _RANDOM[6'h29][23];
