        regfile_3 = 32'h0;
        regfile_4 = 32'h0;
        regfile_5 = 32'h0;
        regfile_6 = 32'h0;
        regfile_7 = 32'h0;
        regfile_8 = 32'h0;
        regfile_9 = 32'h0;
        regfile_10 = 32'h0;
